-- Let's check if there are any marketdata entries that DON'T match orders by mktnote
SELECT count(*) FROM marketdata md
WHERE NOT EXISTS (
    SELECT 1 FROM orders o 
    WHERE o.mktnote = md.quote_depth_snapshot->'metadata'->>'mktcombo'
);

-- Let me check the riskandmargin table more carefully - maybe I need to look at it differently
-- Check how many distinct ordervaults there are and if they all have matching orders
SELECT count(DISTINCT rm.ordervault) FROM riskandmargin rm;
SELECT count(*) FROM riskandmargin rm 
JOIN orders o ON rm.ordervault = o.recordvault;

-- Hmm, let me check the actual join count
SELECT count(*) FROM riskandmargin rm 
JOIN orders o ON rm.ordervault = o.recordvault;

-- Check if all marketdata has the same timetrack
SELECT DISTINCT md.quote_depth_snapshot->'metadata'->>'timetrack' 
FROM marketdata md LIMIT 5;

-- Check all distinct timetracks
SELECT DISTINCT md.quote_depth_snapshot->'metadata'->>'timetrack' 
FROM marketdata md;

-- Check if accountbalancesnode always equals riskandmarginpivot
SELECT count(*) FROM accountbalances ab
JOIN riskandmargin rm ON ab.accountbalancesnode = rm.riskandmarginpivot;

-- Check if all accountbalancesnode values exist in riskandmargin
SELECT count(*) FROM accountbalances ab
WHERE NOT EXISTS (SELECT 1 FROM riskandmargin rm WHERE rm.riskandmarginpivot = ab.accountbalancesnode);

-- Check if all riskandmargin values exist in accountbalances
SELECT count(*) FROM riskandmargin rm
WHERE NOT EXISTS (SELECT 1 FROM accountbalances ab WHERE ab.accountbalancesnode = rm.riskandmarginpivot);
